func (q *Queries) GrepCorpusNotes(ctx context.Context, ownerID pgtype.UUID) ([]GrepCorpusNotesRow, error) {
	rows, err := q.db.Query(ctx, grepCorpusNotes, ownerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GrepCorpusNotesRow
	for rows.Next() {
		var i GrepCorpusNotesRow
		if err := rows.Scan(
			&i.ID,
			&i.Genre,
			&i.Body,
			&i.Published,
			&i.PathTitles,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

